+import { AppError } from "../errors.js";
+import { consume } from "./batches.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+/** Imports validated sale rows atomically, skipping previously imported tickets. */
+export function importSalesRows(store, rows) {
+  const data = structuredClone(store.data);
+  const staged = { data, nextId(kind) { return data.seq[kind] = (data.seq[kind] ?? 0) + 1; } };
+  const previous = new Set(data.sales.map((s) => s.ticket));
+  const tickets = new Set();
+  let dishes = 0;
+  for (const row of rows) {
+    try {
+      const dish = data.dishes.find((d) => d.id === row.dishId);
+      if (!dish) throw new AppError("bad_request", { reason: "unknown dish" });
+      const ingredients = scaled(getRecipe(staged, dish.recipeId), row.qty);
+      if (previous.has(row.ticket)) continue;
+      for (const ingredient of ingredients) {
+        if (ingredient.qty > 0)
+          consume(staged, ingredient.itemId, ingredient.qty, { at: row.soldAt, ref: `sale:${row.ticket}` });
+      }
+      data.sales.push({ ticket: row.ticket, soldAt: row.soldAt, dishId: row.dishId, qty: row.qty, ingredients });
+      tickets.add(row.ticket);
+      dishes += row.qty;
+    } catch (e) {
+      if (!(e instanceof AppError)) throw e;
+      throw new AppError("sales_row", { row: row.row, reason: e.code === "not_enough_stock"
+        ? `not enough stock of ${e.params.item} (${e.params.available} ${e.params.unit} available)`
+        : e.params.reason ?? e.code });
+    }
+  }
+  store.data = data;
+  return { tickets: tickets.size, dishes };
+}
